Method.Source:
    public boolean validate()
    {
        boolean         ret;
        CustTable       metCustTable;
        CustTransOpen   metCustTransOpen;
        CustTrans       metCustTrans;
        FormDataObject  fdo = any2Object(this) as FormDataObject;
        
        ret = next validate();

        metCustTable = fdo.datasource().cursor();

        if (metCustTable.CredManAccountStatusId == METConstants::custAccountStatusClosed)
        {
            select firstonly metCustTransOpen
                where metCustTransOpen.AccountNum == metCustTable.AccountNum;

            select sum(AmountMST) from metCustTrans
                where metCustTrans.AccountNum == metCustTable.AccountNum;

            if (metCustTransOpen && metCustTrans.AmountMST == 0)
            {
                ret = false;
                error ('@MET:METCustAccountStatusValidation');
            }
        }

        if (ret)
        {
            ret = metCustTable.metValidateAccountStatusModified();
        }

        return ret;
    }
